const { headers = {} } = $('Webhook').first().json;
const first = (value) => String(value ?? '').split(',')[0].trim();
const raw = first(headers['x-forwarded-for']) || first(headers['x-real-ip']) || first(headers['cf-connecting-ip']);
const ip = raw.toLowerCase().replace(/^::ffff:(?=\d+\.\d+\.\d+\.\d+$)/, '');

const isIPv4 = (v) => /^\d{1,3}(\.\d{1,3}){3}$/.test(v) && v.split('.').every((part) => Number(part) <= 255);
const isIPv6 = (v) => v.includes(':') && v.length <= 45 && /^[0-9a-f:.]+$/.test(v) && (v.match(/::/g) ?? []).length <= 1;

// Quota day in German time
const date = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Berlin' }).format(new Date());
return [{ json: { ipValid: isIPv4(ip) || isIPv6(ip), ip, date } }];

const PER_IP_LIMIT = 3;
const DAILY_LIMIT = 12;
const { ipValid, ipHash } = $('Hash IP').first().json;
const quota = $input.first().json.body ?? {};
const total = Number(quota.total) || 0;
const mine = Number(quota.ips?.[ipHash]) || 0;
const remaining = ipValid ? Math.max(0, Math.min(PER_IP_LIMIT - mine, DAILY_LIMIT - total)) : 0;

const deny = (status, code, message) => [{ json: { allowed: false, status, code, message, remaining: 0 } }];
if (!ipValid) return deny(400, 'INVALID_CLIENT', 'We could not identify your connection. Please try again later.');
if (total >= DAILY_LIMIT) return deny(429, 'QUOTA_EXCEEDED', 'Our kitchen is closed for today. The daily limit of ' + DAILY_LIMIT + ' generations is reached, please come back tomorrow.');
if (mine >= PER_IP_LIMIT) return deny(429, 'QUOTA_EXCEEDED', 'You have used all ' + PER_IP_LIMIT + ' recipe generations for today. Come back tomorrow or browse the cookbook.');
return [{ json: { allowed: true, remaining } }];

const { headers = {} } = $('Quota webhook').first().json;
const first = (value) => String(value ?? '').split(',')[0].trim();
const raw = first(headers['x-forwarded-for']) || first(headers['x-real-ip']) || first(headers['cf-connecting-ip']);
const ip = raw.toLowerCase().replace(/^::ffff:(?=\d+\.\d+\.\d+\.\d+$)/, '');

const isIPv4 = (v) => /^\d{1,3}(\.\d{1,3}){3}$/.test(v) && v.split('.').every((part) => Number(part) <= 255);
const isIPv6 = (v) => v.includes(':') && v.length <= 45 && /^[0-9a-f:.]+$/.test(v) && (v.match(/::/g) ?? []).length <= 1;

// Quota day in German time
const date = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Berlin' }).format(new Date());
return [{ json: { ipValid: isIPv4(ip) || isIPv6(ip), ip, date } }];

const PER_IP_LIMIT = 3;
const DAILY_LIMIT = 12;
const { ipValid, ipHash } = $('Hash quota IP').first().json;
const quota = $input.first().json.body ?? {};
const total = Number(quota.total) || 0;
const mine = Number(quota.ips?.[ipHash]) || 0;
const remaining = ipValid ? Math.max(0, Math.min(PER_IP_LIMIT - mine, DAILY_LIMIT - total)) : 0;

return [{ json: { remaining, limit: PER_IP_LIMIT } }];
